def choose_move(observation):
    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        if isinstance(v, dict):
            return v.get("x", default[0]), v.get("y", default[1])
        return default

    def clamp_move(dx, dy):
        return [sign(dx), sign(dy)]

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_towards(a, b):
        return clamp_move(b[0] - a[0], b[1] - a[1])

    def step_away(a, b):
        return clamp_move(a[0] - b[0], a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    me = (sx, sy)
    opp = (ox, oy)

    w = observation.get("grid_width", observation.get("width", 0)) or 0
    h = observation.get("grid_height", observation.get("height", 0)) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_towards(me, opp)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        best = corners[0]
        best_score = None
        for c in corners:
            score = dist(c, opp) * 2 - dist(c, me)
            if best_score is None or score > best_score:
                best_score = score
                best = c
        return step_towards(me, best)

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("frontier_cells")
            or observation.get("opponent_territory")
            or observation.get("neutral_cells")
            or []
        )
        best = None
        best_score = None
        for t in targets:
            tx, ty = pos(t, me)
            p = (tx, ty)
            score = -dist(me, p)
            if opp != me:
                score += 0.25 * dist(opp, p)
            if best_score is None or score > best_score:
                best_score = score
                best = p
        if best is not None:
            return step_towards(me, best)
        if w and h:
            center = (w // 2, h // 2)
            return step_towards(me, center)
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    carry = observation.get("carrying", observation.get("load", 0)) or 0
    health = observation.get("health", 0)

    if resources:
        best = None
        best_score = None
        for r in resources:
            rx, ry = pos(r, me)
            p = (rx, ry)
            score = -dist(me, p)
            if opp != me:
                score += 0.15 * dist(opp, p)
            if carry:
                score += 0.05 * dist(p, opp)
            if best_score is None or score > best_score:
                best_score = score
                best = p
        if best is not None:
            return step_towards(me, best)

    if carry and (w and h):
        home = observation.get("home_base") or observation.get("base_position") or observation.get("spawn_position")
        if home:
            hx, hy = pos(home, me)
            return step_towards(me, (hx, hy))
        center = (w // 2, h // 2)
        return step_away(me, opp) if dist(me, opp) <= 2 else step_towards(me, center)

    if health and health <= 2:
        return step_away(me, opp)

    return step_towards(me, opp) if env != "resource_collection" else [0, 0]

